use crate::Analysis;
use crate::analyzers::module_analyzer::visit_expansion;
use fpp_ast::{DefModule, DefPort, SpecTemplateExpand, Visitor, Walkable};
use std::ops::ControlFlow;

/// Check port definitions
pub struct CheckPortDefs;

impl<'ast> Visitor<'ast> for CheckPortDefs {
    type Break = ();
    type State = Analysis;

    /// The members generated by a template expansion are members of the
    /// enclosing module, so analyze them here.
    fn visit_spec_template_expand(
        &self,
        a: &mut Self::State,
        node: &'ast SpecTemplateExpand,
    ) -> ControlFlow<Self::Break> {
        visit_expansion(self, a, node)
    }

    /// Visit translation unit members and module members
    fn visit_def_module(
        &self,
        a: &mut Self::State,
        node: &'ast DefModule,
    ) -> ControlFlow<Self::Break> {
        node.walk(a, self)
    }

    fn visit_def_port(
        &self,
        _a: &mut Self::State,
        node: &'ast DefPort,
    ) -> ControlFlow<Self::Break> {
        if let Err(err) = Analysis::check_for_duplicate_parameter(&node.params) {
            err.emit();
        }
        ControlFlow::Continue(())
    }
}
